 const initialized={installId:g.installId,packetDirectory:'/private/native/packet',authorizationSha256:auth(g),releaseAuthorized:false};
 const remote={state:'failed',phase:'ci-build-health',exit_code:'1',ref:g.source,build_id:g.build.nextBuildId,built_ref:g.baseline,built_build_id:g.baselineBuildId,stale_build:'1',log:'/var/tmp/aihr-deploy/deploy-fixture.log',pid:'987',started_at:'1',finished_at:'2'};
 const records={'prelaunch-request.json':r,'parent-qualification.json':{id:33,head_sha:c.prelaunchRevision,head_branch:'codex/board-prelaunch-resume-20261119',path:'.github/workflows/prelaunch-operator-development.yml',event:'push',run_attempt:1,status:'completed',conclusion:'success',repository:{id:1333414856},head_repository:{id:1333414856}},'canonical-reauthentication.json':{policy:r.policy,operatorHead:c.prelaunchRevision,verifier:r.verifier,witnessFingerprint:g.witnessFingerprint,oldGrantNotRevoked:true,at:new Date(Date.parse(old.issuedAt)+1000).toISOString()},'original-native-prelaunch-proof.json':{...r,noNativeBegin:true,noNativeProcess:true,oldUnlaunched:true,pending:r.source,oldGrantNotRevoked:true,compiledMetadataSha256:d,packetSha256:d,baselineManifestSha256:d,environmentSha256:d,compiledBytesVerified:true,releaseAuthorized:false},'installation-grant.json':g,'installation-initialized.json':initialized,'installation-linked.json':{policy:r.policy,oldInstallId:old.installId,installId:g.installId,copyVerified:true,releaseAuthorized:false,linkSha256:d,acknowledgement:clone(initialized)},'launch.json':{policy:r.policy,oldInstallId:old.installId,installId:g.installId,launchReserved:true,releaseAuthorized:false,output:'aihr-deploy-log='+remote.log+'\n'},'remote-build-result.json':remote};
 return {c,records,verification,oldPreflight,oldGrant:old,oldAcknowledgement,owners:{...grantOwner,...canonical,...parent},target:STAGING,provenance:{fictional:true},lease};
