test('canonical VIEW derives checked new launch identity without rewriting any actual original record',()=>{
 const f=fixture(),before=JSON.stringify(f),v=canonicalEvidenceView(f);assert.equal(JSON.stringify(f),before);assert.equal(v.view.grant,f.records['installation-grant.json']);assert.equal(v.view.initialized,f.records['installation-initialized.json']);assert.equal(v.view.remoteBuild,f.records['remote-build-result.json']);assert.equal(v.view.preflight.verificationController,f.c.canonicalRevision);assert.equal(v.view.preflight.canonicalView.notOriginalRecord,true);assert.equal(v.view.launch.testingBuildRecordId,v.grant.build.buildRecordId);assert.equal(f.records['launch.json'].testingBuildRecordId,undefined);
});
for(const [name,edit]of [
 ['running deployment',f=>f.records['remote-build-result.json'].state='running'],['already successful deployment',f=>f.records['remote-build-result.json'].state='ok'],['wrong native phase',f=>f.records['remote-build-result.json'].phase='migrations'],['wrong terminal exit',f=>f.records['remote-build-result.json'].exit_code='2'],['another actual log',f=>f.records['remote-build-result.json'].log+='.other'],['missing failure record',f=>delete f.records['remote-build-result.json']],['wrong CI witness',f=>f.verification.fingerprint='a'.repeat(64)],['wrapper substituted for canonical verifier',f=>f.verification.verificationController=f.c.prelaunchRevision],['wrong grant',f=>f.records['installation-grant.json'].build.nextBuildId='foreign'],['wrong original grant',f=>f.oldGrant.installId=f.records['installation-grant.json'].installId],['missing durable copy',f=>f.records['installation-linked.json'].copyVerified=false],['wrong acknowledgement',f=>f.records['installation-initialized.json'].authorizationSha256='a'.repeat(64)],['unreserved launch',f=>f.records['launch.json'].launchReserved=false],['wrong parent qualification',f=>f.records['parent-qualification.json'].head_sha='a'.repeat(40)],['late reauthentication',f=>f.records['canonical-reauthentication.json'].at=new Date().toISOString()],['other staging target',f=>f.oldPreflight.target={...STAGING,host:'foreign'}],
])test('canonical VIEW refuses '+name,()=>{const f=fixture();edit(f);assert.throws(()=>canonicalEvidenceView(f));});
function worker(){const f=fixture(),grant=f.records['installation-grant.json'],helperBytes=Buffer.from('fictional qualified helper'),approval={helperSha256:hash(helperBytes),identity:{source:grant.source},install:{id:grant.installId,buildRecordId:grant.build.buildRecordId},lease:{...f.lease,candidate:grant.source}},approvalBytes=Buffer.from(JSON.stringify(approval)+'\n');const names=['format','installer_v2','fences_v1','ci_runtime_v1','operation_guard_v1','upgrade_v1','prepared_v1','published_v1','unstarted_v1'];const assembly={helperSha256:hash(helperBytes),bytes:helperBytes.length,releaseAuthorized:false,sourceFiles:Object.fromEntries(names.map(n=>['deploy/systemd/bank_import_worker_'+n+'.py',d]))};const receipt={mode:'recover-unstarted-ci-runtime',policy:'aihr-worker-unstarted-recovery/v1',unstartedRecoveryPolicy:'aihr-worker-unstarted-recovery/v1',workerRecoveryOnly:true,source:grant.source,webBuildId:grant.build.nextBuildId,installId:grant.installId,installationAuthorizationSha256:grantOwner.installHash(Buffer.from(grantOwner.installJson(grant)+'\n')),authorizationSha256:hash(approvalBytes),serviceStable:true,journeyVerified:false,nativeRuntimeVerified:true,fullSourceContentInventoryVerified:true,fullNativeAudits:2,completeMetadataFences:10,transitionStages:Array(10).fill('F'),leasePhases:Array(10).fill('installing')};return {receipt,approval,approvalBytes,helperBytes,assembly,grant,owners:f.owners,lease:f.lease};}
test('actual full native F receipt must bind approved helper, held lease and actual new web installation',()=>{const f=worker();assert.equal(workerReceiptReady(f),f.receipt);});
for(const [name,edit]of [['ordinary mode',f=>f.receipt.mode='activate-ci-runtime'],['old installation',f=>f.receipt.installId='other'],['wrong approval',f=>f.receipt.authorizationSha256='a'.repeat(64)],['wrong helper',f=>f.approval.helperSha256='a'.repeat(64)],['wrong lease',f=>f.approval.lease.epoch++],['one audit',f=>f.receipt.fullNativeAudits=1],['nine fences',f=>f.receipt.completeMetadataFences=9],['normal-stage receipt',f=>f.receipt.transitionStages[1]='O'],['wrong graph',f=>delete f.assembly.sourceFiles['deploy/systemd/bank_import_worker_format.py']],['failed receipt',f=>f.receipt.error='failure']])test('worker receipt refuses '+name,()=>{const f=worker();edit(f);assert.throws(()=>workerReceiptReady(f));});
test('qualification is exact code, branch, workflow, event and first successful attempt',()=>{const q=fixture().records['parent-qualification.json'],expected={id:q.id,head:q.head_sha,branch:q.head_branch,path:q.path};qualified(q,expected);for(const change of [{event:'workflow_dispatch'},{run_attempt:2},{conclusion:'failure'},{head_sha:'a'.repeat(40)},{head_branch:'main'},{path:'other.yml'}])assert.throws(()=>qualified({...q,...change},expected));});
function canonicalRun(){
 const f=fixture(),v=canonicalEvidenceView(f),g=v.grant,auth=grantOwner.installHash(Buffer.from(grantOwner.installJson(g)+'\n')),expectedLedger=[{tag:'fixture',hash:d,created_at:'1'}],rows=[{id:'1',hash:d,created_at:'1'}];
 const ledger={kind:'READ_ONLY_EXACT_MIGRATION_LEDGER_NOT_RELEASE',releaseAuthorized:false,rows:1,expectedSha256:grantOwner.installHash(grantOwner.installJson(expectedLedger)),actualSha256:grantOwner.installHash(grantOwner.installJson(rows))};
 const tuple={format:1,source:g.source,installId:g.installId,buildRecordId:g.build.buildRecordId,nextBuildId:g.build.nextBuildId,authorizationSha256:auth,releaseAuthorized:false};
 const active={...tuple,kind:'CI_BUILD_ACTIVE_SERVICE_VERIFIED_NOT_FULL_ARRIVAL',healthStatus:200,fullMigrationLedgerVerified:true,pid:'4321',migrationLedger:ledger},activated={...tuple,kind:'CI_BUILD_BYTES_ACTIVATED_NOT_FULL_ARRIVAL',activation:{activeBuildId:g.build.nextBuildId}};
 const log=JSON.stringify(activated)+'\n'+JSON.stringify(active)+'\n'+canonical.WORKER_FAILURE_MARKER+'2).';
 const events=[],save=()=>{},state={worker:'Import worker ready for: bank_import, employee_import.\n',checksum:'',rows};
 const options={execute:true,candidate:g.source,controller:f.c.canonicalRevision,runId:g.runId,target:STAGING,evidence:v.view,expectedLedger,lease:{...f.lease,candidate:g.source},save,frozen:()=>{},ports:{leaseAssert:()=>({releaseAuthorized:false,...f.lease,candidate:g.source,phase:'installing'}),follow:()=>{events.push('follow');return {log,status:v.view.remoteBuild};},worker:()=>{events.push('worker');if(state.worker instanceof Error)throw state.worker;return state.worker;},service:()=>{events.push('service');return 'service=active\n{"healthStatus":200,"body":"{\\"status\\":\\"ok\\"}"}\n';},checksum:()=>{events.push('checksum');return state.checksum;},installer:()=>"['stage','activate','confirm-runtime','status','resume-status', allowExpired:mode==='resume-status'",ledger:()=>{events.push('ledger');return state.rows;},finish:()=>{events.push('finish');return 'finished';},status:()=>({...v.view.remoteBuild,state:'ok',exit_code:'0',built_ref:g.source,built_build_id:g.build.nextBuildId,stale_build:'0'}),requireBuilt:s=>assert(s.state==='ok'&&s.ref===g.source),arrive:async()=>{events.push('arrival');return {arrival:{source:g.source},ownedResourceCleanupVerified:false};}}};
 return {options,events,state};
}
test('actual unchanged canonical API verifies VIEW read-only, then alone owns finish and arrival after every port',async()=>{
 const v=canonicalRun();v.options.execute=false;const checked=await canonical.resumeArrival(v.options);assert.equal(checked.result,'ADMISSIBLE_NOT_EXECUTED');assert(!v.events.includes('finish'));
 const e=canonicalRun(),done=await canonical.resumeArrival(e.options);assert.equal(done.result,'ARRIVED');assert.equal(e.events.filter(n=>n==='finish').length,1);assert.equal(e.events.filter(n=>n==='follow').length,2);for(const n of ['worker','service','checksum','ledger'])assert(e.events.indexOf(n)<e.events.indexOf('finish'));assert(e.events.indexOf('finish')<e.events.indexOf('arrival'));
});
for(const [name,edit]of [['worker not restored',f=>f.state.worker=new Error('not ready')],['source drift',f=>f.state.checksum='changed'],['ledger drift',f=>f.state.rows=[{id:'1',hash:'a'.repeat(64),created_at:'1'}]]])test('canonical API refuses before finish when '+name,async()=>{const f=canonicalRun();edit(f);await assert.rejects(()=>canonical.resumeArrival(f.options));assert(!f.events.includes('finish'));assert(!f.events.includes('arrival'));});

test('SSH port redacts guarded lease tokens before canonical evidence/error handling sees them',()=>{const token='9'.repeat(64);assert.throws(()=>sshCommand(['AIHR_STAGING_TOKEN='+token],{},()=>{throw new Error('ssh failed AIHR_STAGING_TOKEN='+token);}),e=>!e.message.includes(token)&&e.message.includes('<REDACTED>'));});

function publishedWorker(){const f=worker();Object.assign(f.receipt,{mode:'recover-ci-runtime',policy:'aihr-worker-prepared-handoff/v1',publishedRecoveryOnly:true,publishedSealSha256:d});delete f.receipt.unstartedRecoveryPolicy;Object.assign(f.approval,{kind:'ADMIN_AUTHORIZED_PUBLISHED_WORKER_RECOVERY',recovery:{policy:'aihr-worker-unstarted-recovery/v1'},publishedSeal:{sha256:d},publishedFailure:{originPolicy:'aihr-worker-unstarted-recovery/v1',approvalSha256:d,members:Object.fromEntries(['activation-failed.json','activation-failure-observation.json','ci-runtime-started.json','ci-runtime-full-audit-0.json','ci-worker-start-request.json','ci-worker-started.json','ci-worker-quarantine-authority.json',...Array.from({length:5},(_,i)=>'ci-runtime-fence-0'+i+'.json')].map(n=>[n,{sha256:d}]))}});f.approvalBytes=Buffer.from(JSON.stringify(f.approval)+'\n');f.receipt.authorizationSha256=hash(f.approvalBytes);return f;}
test('explicit published-unstarted recovery admits only actual full successful native receipt bound to exact F5 origin',()=>{const f=publishedWorker();assert.equal(workerReceiptReady(f),f.receipt);});
for(const [name,edit]of [['generic published origin',f=>delete f.approval.publishedFailure.originPolicy],['other historical policy',f=>f.approval.recovery.policy='other'],['missing F4',f=>delete f.approval.publishedFailure.members['ci-runtime-fence-04.json']],['extra original member',f=>f.approval.publishedFailure.members['foreign.json']={}],['another published seal',f=>f.receipt.publishedSealSha256='a'.repeat(64)],['partial graph',f=>f.receipt.completeMetadataFences=5],['old F5 failure as receipt',f=>Object.assign(f.receipt,{accepted:false,serviceStable:false})]])test('published-unstarted receipt refuses '+name,()=>{const f=publishedWorker();edit(f);assert.throws(()=>workerReceiptReady(f));});

function profiledWorker(){const f=publishedWorker();f.approval.recoveryBudgetProfile='aihr-worker-unstarted-published-budget/v1';f.receipt.recoveryBudgetProfile=f.approval.recoveryBudgetProfile;f.approvalBytes=Buffer.from(JSON.stringify(f.approval)+'\n');f.receipt.authorizationSha256=hash(f.approvalBytes);return f;}
test('named budget-neutral profile requires identical exact native receipt and root live approval selection',()=>{const f=profiledWorker();assert.equal(workerReceiptReady(f),f.receipt);});
for(const [name,edit]of [['receipt omission',f=>delete f.receipt.recoveryBudgetProfile],['approval omission',f=>delete f.approval.recoveryBudgetProfile],['unknown profile',f=>f.receipt.recoveryBudgetProfile='aihr-worker-unstarted-published-budget/v2'],['object instead of policy string',f=>f.receipt.recoveryBudgetProfile={policy:'aihr-worker-unstarted-published-budget/v1'}],['wrong origin',f=>f.approval.publishedFailure.originPolicy='other'],['unstarted route',f=>Object.assign(f.receipt,{mode:'recover-unstarted-ci-runtime',policy:'aihr-worker-unstarted-recovery/v1',unstartedRecoveryPolicy:'aihr-worker-unstarted-recovery/v1'})],['partial profiled graph',f=>f.receipt.completeMetadataFences=9]])test('budget profile refuses '+name,()=>{const f=profiledWorker();edit(f);assert.throws(()=>workerReceiptReady(f));});
